/* HUWiki OAuth: consent is requested per operation, never stored in a shared tiddler. */
'use strict';
var VERSION='2026-10-26.2';
var URL='https://huwiki.xn--mns-ula.dk/privacy.html';
function danish(){try{return /da|dansk|danish/i.test($tw.wiki.getTiddlerText('$:/language',''));}catch(e){return false;}}
exports.approve=function(c,details){
 var da=danish(),description=typeof details==="object"?(da?details.da:details.en):String(details||"");
 if(!window.confirm((da?"Send til ":"Send to ")+(c.name||c.provider)+" · "+c.model+"\n\n"+description+"\n\n"+(da?"Forbindelsen bruger den konto, ejeren har godkendt. Gemte AI-svar kan læses af wikiens øvrige læsere.":"This connection uses the account approved by its owner. Saved AI replies can be read by other wiki readers.")))return null;
 return {approved:true};
};
exports.notice=function(root){
 var d=root.ownerDocument,p=d.createElement('p'),a=d.createElement('a');p.className='huwiki-ai-help';
 a.href=URL;a.target='_blank';a.rel='noopener noreferrer';a.textContent=danish()?'AI og privatliv — læs før afsendelse':'AI and privacy — read before sending';p.appendChild(a);root.appendChild(p);
};

/* External chat: copy only the visible draft, never conversation history or keys. */
exports.externalGemini=function(root,getText){
 var da=danish(),d=root.ownerDocument,box=d.createElement('div'),copy=d.createElement('button'),link=d.createElement('a'),status=d.createElement('p');
 box.className='huwiki-ai-help';copy.type='button';copy.className='huw-ai-secondary';
 copy.textContent=da?'Kopiér teksten':'Copy text';
 link.textContent=da?'Åbn Gemini ↗':'Open Gemini ↗';link.href='https://gemini.google.com/';link.target='_blank';link.rel='noopener noreferrer';link.className='huw-ai-secondary';
 status.setAttribute('role','status');status.setAttribute('aria-live','polite');
 status.textContent=da?'Kopiér din besked og indsæt den selv i Gemini. Billeder og samtalehistorik medtages ikke. Googles adgangskrav og datavilkår gælder.':'Copy your message and paste it into Gemini yourself. Images and conversation history are not included. Google’s access requirements and data terms apply.';
 copy.addEventListener('click',function(){
  var text=String(getText()||'');
  if(!text.trim()){status.textContent=da?'Skriv først en besked i tekstfeltet.':'First enter a message in the text field.';return;}
  function done(){status.textContent=da?'Teksten er kopieret. Åbn Gemini og indsæt den dér.':'Text copied. Open Gemini and paste it there.';}
  function fallback(){
   var area=d.createElement('textarea'),previous=d.activeElement;area.value=text;area.readOnly=true;box.appendChild(area);area.focus();area.select();
   var ok=false;try{ok=d.execCommand('copy');}catch(ignore){}
   if(ok){box.removeChild(area);if(previous&&previous.focus)previous.focus();done();}
   else{status.textContent=da?'Automatisk kopiering blev blokeret. Kopiér den markerede tekst manuelt.':'Automatic copying was blocked. Copy the selected text manually.';}
  }
  var nav=d.defaultView&&d.defaultView.navigator;
  if(nav&&nav.clipboard&&nav.clipboard.writeText){try{Promise.resolve(nav.clipboard.writeText(text)).then(done,fallback);}catch(ignore){fallback();}}else fallback();
 });
 box.appendChild(copy);box.appendChild(d.createTextNode(' '));box.appendChild(link);box.appendChild(status);root.appendChild(box);
};
